/* Ecosystem Config website service worker (generated by site/scripts/postbuild.mjs).
 * - Same-origin only: registry JSON consumers fetch from raw.githubusercontent.com and are never touched.
 * - Pages are network-first, so an online visit always gets the newest build (and its newer data snapshot).
 * - Hashed build assets are cache-first; every new version deletes the previous caches on activation. */
const VERSION = "__VERSION__";
const SHELL = `ec-shell-${VERSION}`;
const MEDIA = `ec-media-${VERSION}`;
const PRECACHE = __PRECACHE__;
const BASE = new URL(self.registration.scope).pathname;

self.addEventListener("install", event => {
  event.waitUntil(caches.open(SHELL).then(cache => cache.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", event => {
  event.waitUntil(caches.keys()
    .then(keys => Promise.all(keys.filter(key => key.startsWith("ec-") && key !== SHELL && key !== MEDIA).map(key => caches.delete(key))))
    .then(() => self.clients.claim()));
});

async function trimMedia(limit = 80) {
  const cache = await caches.open(MEDIA);
  const keys = await cache.keys();
  await Promise.all(keys.slice(0, Math.max(0, keys.length - limit)).map(key => cache.delete(key)));
}

self.addEventListener("fetch", event => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== "GET" || url.origin !== self.location.origin || !url.pathname.startsWith(BASE)) return;

  if (request.mode === "navigate") {
    event.respondWith(fetch(request).then(response => {
      if (response.ok) { const copy = response.clone(); caches.open(SHELL).then(cache => cache.put(request, copy)); }
      return response;
    }).catch(async () => (await caches.match(request, { ignoreSearch: true, ignoreVary: true }))
      ?? (await caches.match(`${BASE}404.html`)) ?? (await caches.match(BASE)) ?? Response.error()));
    return;
  }

  if (url.pathname.startsWith(`${BASE}generated/projects/`)) {
    event.respondWith(caches.open(MEDIA).then(async cache => {
      const cached = await cache.match(request, { ignoreVary: true });
      const network = fetch(request).then(response => { if (response.ok) { cache.put(request, response.clone()); trimMedia(); } return response; });
      if (cached) { network.catch(() => {}); return cached; }
      return network;
    }));
    return;
  }

  // Module scripts are CORS-mode requests; ignore Vary so a precached copy always matches its URL.
  event.respondWith(caches.match(request, { ignoreVary: true }).then(cached => cached ?? fetch(request)));
});
